// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }

    function testFuzz_property(address depositor, uint256 amount) public {
        amount = bound(amount, 1, 1 ether);

        vm.deal(depositor, amount);
        uint256 beforeContractBalance = address(c).balance;

        vm.prank(depositor);
        c.deposit{value: amount}();

        uint256 afterContractBalance = address(c).balance;

        vm.prank(depositor);
        c.withdraw(amount);

        vm.prank(depositor);
        c.refund();

        uint256 finalContractBalance = address(c).balance;

        assertTrue(finalContractBalance == beforeContractBalance);
    }
}
